//! Structural symmetries of a Petri net.
//!
//! A symmetry is an automorphism of the net that permutes places and
//! transitions while preserving arc weights (and, when requested, the initial
//! marking). The implementation computes a sound subgroup generated by
//! place/transition transpositions whose incidence signatures are identical,
//! then exposes the orbit quotient so reachability can be explored on
//! canonical markings (one representative per orbit) instead of the full
//! state space.

use std::collections::HashMap;

use racon_core::marking::{Marking, TokenValue};
use racon_core::net::PetriNet;
use std::cmp::Ordering;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SymmetryOptions {
    /// Only accept automorphisms that fix the initial marking.
    pub respect_initial_marking: bool,
    /// Places that must remain fixed by every accepted automorphism.
    pub fixed_places: Vec<u32>,
    /// Transitions that must remain fixed by every accepted automorphism.
    pub fixed_transitions: Vec<u32>,
}

impl Default for SymmetryOptions {
    fn default() -> Self {
        Self {
            respect_initial_marking: true,
            fixed_places: Vec::new(),
            fixed_transitions: Vec::new(),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SymmetryGeneratorKind {
    PlaceTransposition,
    TransitionTransposition,
}

impl SymmetryGeneratorKind {
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::PlaceTransposition => "PLACE_TRANSPOSITION",
            Self::TransitionTransposition => "TRANSITION_TRANSPOSITION",
        }
    }
}

/// One generator of the symmetry group, written as a transposition.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SymmetryGenerator {
    pub kind: SymmetryGeneratorKind,
    pub first: u32,
    pub second: u32,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct SymmetryReport {
    pub generators: Vec<SymmetryGenerator>,
    pub generator_count: usize,
    pub group_size: u128,
    pub place_equivalence_classes: Vec<Vec<u32>>,
    pub transition_equivalence_classes: Vec<Vec<u32>>,
}

impl SymmetryReport {
    #[allow(dead_code)]
    fn trivial() -> Self {
        Self {
            generators: Vec::new(),
            generator_count: 0,
            group_size: 1,
            place_equivalence_classes: Vec::new(),
            transition_equivalence_classes: Vec::new(),
        }
    }
}

/// Precomputed symmetry of one net, able to canonicalize markings.
#[derive(Debug, Clone)]
pub struct Symmetry {
    place_components: Vec<Vec<u32>>,
    report: SymmetryReport,
}

impl Symmetry {
    /// Compute the symmetry group and orbit decomposition.
    pub fn compute(net: &PetriNet, options: &SymmetryOptions) -> Self {
        let places = net.place_count();
        let transitions = net.transition_count();

        // Arc weight matrices: place→transition and transition→place.
        let mut place_to_transition = vec![vec![0u32; transitions]; places];
        let mut transition_to_place = vec![vec![0u32; places]; transitions];
        for transition in net.transitions() {
            let t = transition.id.0 as usize;
            for &(place, weight) in net.preset(transition.id) {
                place_to_transition[place.0 as usize][t] = weight;
            }
            for &(place, weight) in net.postset(transition.id) {
                transition_to_place[t][place.0 as usize] = weight;
            }
        }

        let fixed_places: Vec<bool> = (0..places)
            .map(|p| options.fixed_places.contains(&(p as u32)))
            .collect();
        let fixed_transitions: Vec<bool> = (0..transitions)
            .map(|t| options.fixed_transitions.contains(&(t as u32)))
            .collect();

        let mut generators = Vec::new();

        // ── place transpositions ──
        let mut place_groups: HashMap<(Vec<u32>, Vec<u32>), Vec<usize>> = HashMap::new();
        for p in 0..places {
            let column: Vec<u32> = (0..transitions).map(|t| transition_to_place[t][p]).collect();
            place_groups
                .entry((place_to_transition[p].clone(), column))
                .or_default()
                .push(p);
        }
        let mut place_union = UnionFind::new(places);
        for group in place_groups.values() {
            for i in 0..group.len() {
                for j in (i + 1)..group.len() {
                    let (p, q) = (group[i], group[j]);
                    if fixed_places[p] || fixed_places[q] {
                        continue;
                    }
                    if options.respect_initial_marking
                        && net.initial_marking().tokens[p] != net.initial_marking().tokens[q]
                    {
                        continue;
                    }
                    place_union.union(p, q);
                    generators.push(SymmetryGenerator {
                        kind: SymmetryGeneratorKind::PlaceTransposition,
                        first: p as u32,
                        second: q as u32,
                    });
                }
            }
        }

        // ── transition transpositions ──
        let mut transition_groups: HashMap<(Vec<u32>, Vec<u32>), Vec<usize>> = HashMap::new();
        for t in 0..transitions {
            let column: Vec<u32> = (0..places).map(|p| place_to_transition[p][t]).collect();
            transition_groups
                .entry((transition_to_place[t].clone(), column))
                .or_default()
                .push(t);
        }
        let mut transition_union = UnionFind::new(transitions);
        for group in transition_groups.values() {
            for i in 0..group.len() {
                for j in (i + 1)..group.len() {
                    let (t, u) = (group[i], group[j]);
                    if fixed_transitions[t] || fixed_transitions[u] {
                        continue;
                    }
                    transition_union.union(t, u);
                    generators.push(SymmetryGenerator {
                        kind: SymmetryGeneratorKind::TransitionTransposition,
                        first: t as u32,
                        second: u as u32,
                    });
                }
            }
        }

        let place_components = place_union.non_trivial_components();
        let transition_components = transition_union.non_trivial_components();

        let mut group_size: u128 = 1;
        for component in place_components.iter().chain(transition_components.iter()) {
            group_size = group_size.saturating_mul(factorial(component.len()));
        }

        let report = SymmetryReport {
            generator_count: generators.len(),
            generators,
            group_size,
            place_equivalence_classes: place_components.clone(),
            transition_equivalence_classes: transition_components,
        };

        Self {
            place_components,
            report,
        }
    }

    pub fn is_trivial(&self) -> bool {
        self.report.generator_count == 0
    }

    pub fn report(&self) -> &SymmetryReport {
        &self.report
    }

    pub fn place_equivalence_classes(&self) -> &[Vec<u32>] {
        &self.report.place_equivalence_classes
    }

    pub fn transition_equivalence_classes(&self) -> &[Vec<u32>] {
        &self.report.transition_equivalence_classes
    }

    /// Return the canonical (lexicographically smallest) representative of the
    /// orbit of `marking` under the computed symmetry group.
    pub fn canonicalize(&self, marking: &Marking) -> Marking {
        if self.place_components.is_empty() {
            return marking.clone();
        }
        let mut tokens = marking.tokens.clone();
        for component in &self.place_components {
            let mut values: Vec<TokenValue> =
                component.iter().map(|&p| tokens[p as usize].clone()).collect();
            values.sort_by(token_order);
            for (slot, value) in component.iter().zip(values.into_iter()) {
                tokens[*slot as usize] = value;
            }
        }
        Marking::new(tokens)
    }
}

fn token_order(left: &TokenValue, right: &TokenValue) -> Ordering {
    if left == right {
        Ordering::Equal
    } else if left.geq(right) {
        Ordering::Greater
    } else {
        Ordering::Less
    }
}

fn factorial(value: usize) -> u128 {
    (1..=value as u128).product::<u128>().max(1)
}

/// Minimal union-find used to build orbit components.
struct UnionFind {
    parent: Vec<usize>,
}

impl UnionFind {
    fn new(size: usize) -> Self {
        Self {
            parent: (0..size).collect(),
        }
    }

    fn find(&mut self, mut node: usize) -> usize {
        while self.parent[node] != node {
            self.parent[node] = self.parent[self.parent[node]];
            node = self.parent[node];
        }
        node
    }

    fn union(&mut self, first: usize, second: usize) {
        let root_first = self.find(first);
        let root_second = self.find(second);
        if root_first != root_second {
            self.parent[root_second] = root_first;
        }
    }

    /// Return only components with more than one element.
    fn non_trivial_components(&mut self) -> Vec<Vec<u32>> {
        let mut buckets: HashMap<usize, Vec<u32>> = HashMap::new();
        for node in 0..self.parent.len() {
            let root = self.find(node);
            buckets.entry(root).or_default().push(node as u32);
        }
        let mut components: Vec<Vec<u32>> = buckets
            .into_values()
            .filter(|component| component.len() > 1)
            .collect();
        components.sort();
        components
    }
}

/// `COMPUTE_SYMMETRIES` operation from the protocol.
pub fn compute_symmetries(net: &PetriNet, options: &SymmetryOptions) -> SymmetryReport {
    Symmetry::compute(net, options).report().clone()
}

/// Partial convenience constructors for the protocol DTOs.
pub fn transposition_generator_pairs(report: &SymmetryReport) -> Vec<(u32, u32)> {
    report
        .generators
        .iter()
        .map(|generator| (generator.first, generator.second))
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use racon_core::net::{ArcEndpoint, PetriNetBuilder};

    /// Two places with identical incidence (both consume from and produce into
    /// the same transition). They are place-only symmetric when the initial
    /// marking agrees.
    fn twin_places_net(initial: [u64; 2]) -> PetriNet {
        let mut builder = PetriNetBuilder::default();
        let p0 = builder.add_place("p0".into(), None);
        let p1 = builder.add_place("p1".into(), None);
        let t0 = builder.add_transition("t0".into(), None);
        builder.add_arc(ArcEndpoint::Place(p0), ArcEndpoint::Transition(t0), 1);
        builder.add_arc(ArcEndpoint::Place(p1), ArcEndpoint::Transition(t0), 1);
        builder.add_arc(ArcEndpoint::Transition(t0), ArcEndpoint::Place(p0), 1);
        builder.add_arc(ArcEndpoint::Transition(t0), ArcEndpoint::Place(p1), 1);
        builder
            .build(vec![TokenValue::Finite(initial[0]), TokenValue::Finite(initial[1])])
            .unwrap()
    }

    #[test]
    fn asymmetric_initial_marking_breaks_the_symmetry() {
        let net = twin_places_net([2, 0]);
        let symmetry = Symmetry::compute(&net, &SymmetryOptions::default());
        assert!(symmetry.is_trivial());
        assert_eq!(symmetry.report().group_size, 1);
    }

    #[test]
    fn canonicalization_sorts_within_an_orbit() {
        let net = twin_places_net([0, 0]);
        let symmetry = Symmetry::compute(&net, &SymmetryOptions::default());
        assert!(!symmetry.is_trivial());
        assert_eq!(symmetry.report().group_size, 2);
        let marking = Marking::from_finite(&[3, 1]);
        assert_eq!(symmetry.canonicalize(&marking), Marking::from_finite(&[1, 3]));
        // Already canonical markings are unchanged.
        let canonical = Marking::from_finite(&[1, 3]);
        assert_eq!(symmetry.canonicalize(&canonical), canonical);
    }

    #[test]
    fn fixed_places_are_excluded_from_the_group() {
        let net = twin_places_net([0, 0]);
        let options = SymmetryOptions {
            respect_initial_marking: true,
            fixed_places: vec![0],
            fixed_transitions: Vec::new(),
        };
        let symmetry = Symmetry::compute(&net, &options);
        assert!(symmetry.is_trivial());
    }

    #[test]
    fn respect_initial_marking_false_keeps_structural_symmetry() {
        let net = twin_places_net([2, 0]);
        let options = SymmetryOptions {
            respect_initial_marking: false,
            ..SymmetryOptions::default()
        };
        let symmetry = Symmetry::compute(&net, &options);
        assert!(!symmetry.is_trivial());
        assert_eq!(symmetry.report().group_size, 2);
    }

    #[test]
    fn report_lists_generators_and_equivalence_classes() {
        let net = twin_places_net([0, 0]);
        let report = compute_symmetries(&net, &SymmetryOptions::default());
        assert_eq!(report.generator_count, 1);
        assert_eq!(report.place_equivalence_classes, vec![vec![0, 1]]);
    }
}
